from flask import Flask, jsonify
import threading
import time

app = Flask(__name__)
started_at = time.time()
ready = False

@app.route('/health/startup')
def startup():
    """检查应用是否完成初始化"""
    if time.time() - started_at < 30:  # 需要 30s 初始化
        return jsonify({"status": "starting"}), 503
    return jsonify({"status": "started"}), 200

